CREATE OR REPLACE FUNCTION combat_consumer_private.after_publish(p_round uuid, p_next uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ctx combat_consumer_private.activities%rowtype; r public.combat_v2_rounds%rowtype;
  next_actor uuid;
begin
  if not combat_consumer_private.owns_round(p_round) then return; end if;
  select * into r from public.combat_v2_rounds where id=p_round;
  select * into ctx from combat_consumer_private.activities where session_id=r.session_id for update;
  if ctx.exchange_id is distinct from p_round or ctx.phase<>'resolved' or r.state<>'narrato'
    or not exists(select 1 from public.combat_v2_round_reports where round_id=p_round
      and narration_state='pubblicata' and message_id is not null) then
    raise exception 'ordinary_publication_state_invalid';
  end if;
  if p_next is null then
    if (select count(*) from public.combat_v2_actors where session_id=ctx.session_id and state='attivo' and companion_id is null)>=2 then
      raise exception 'ordinary_next_missing';
    end if;
    perform combat_consumer_private.close_session(ctx.session_id);
    return;
  end if;
  if not exists(select 1 from public.combat_v2_rounds where id=p_next and session_id=ctx.session_id
    and round_no=r.round_no+1 and phase='raccolta_azioni') then
    raise exception 'ordinary_next_invalid';
  end if;
  select m.actor_id into next_actor from combat_consumer_private.members m
    join public.combat_v2_actors a on a.id=m.actor_id and a.session_id=m.session_id
    where m.session_id=ctx.session_id and m.actor_id<>ctx.turn_actor_id and a.state='attivo';
  if next_actor is null then raise exception 'ordinary_next_actor_invalid'; end if;
  update combat_consumer_private.activities set exchange_id=p_next,turn_actor_id=next_actor,
    round_no=ctx.round_no+case when mod(r.round_no,2)=0 then 1 else 0 end,
    phase='action',context_version=context_version+1,last_action_at=clock_timestamp()
    where session_id=ctx.session_id;
  update combat_consumer_private.offers set state='revoked'
    where session_id=ctx.session_id and state='offered';
end $function$

CREATE OR REPLACE FUNCTION combat_consumer_private.before_publish(p_round uuid, p_kind text, p_text text, p_request uuid, p_author uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ctx combat_consumer_private.activities%rowtype; authority combat_consumer_private.narrative_authorities%rowtype;
  text_sha text;
begin
  if not combat_consumer_private.owns_round(p_round) then return; end if;
  select * into ctx from combat_consumer_private.activities where exchange_id=p_round for update;
  select * into authority from combat_consumer_private.narrative_authorities where session_id=ctx.session_id for update;
  if ctx.phase is distinct from 'resolved' then raise exception 'ordinary_publish_context_invalid'; end if;
  if exists(select 1 from combat_consumer_private.recovery_claims_v1 where round_id=p_round) then
    if p_kind='fato_ia' and p_author is null and combat_consumer_private.is_service_request()
      and exists(select 1 from combat_consumer_private.recovery_publish_authorizations_v1 p
        join combat_consumer_private.recovery_claims_v1 c on c.id=p.claim_id
        join combat_consumer_private.recovery_attempts_v1 a on a.claim_id=c.id
        where p.round_id=p_round and p.request_key=p_request and p.transaction_id=txid_current()
          and p.state='prepared' and a.state='generated'
          and p.text_sha256=encode(extensions.digest(convert_to(p_text,'UTF8'),'sha256'),'hex')
          and combat_consumer_private.recovery_current_v1(c.id)) then return; end if;
    raise exception 'recovery_publish_authority_required';
  end if;
  if p_kind='fato_umano' and authority.mode='human' and p_author is not null and p_author=auth.uid()
    and exists(select 1 from public.master_v2_sessions where id=authority.master_session_id
      and master_user=auth.uid() and owner_kind='human' and stato='in_corso') then return; end if;
  if p_kind<>'fato_ia' or p_author is not null or not combat_consumer_private.is_service_request() then
    raise exception 'ordinary_narrative_authority_invalid';
  end if;
  text_sha:=encode(extensions.digest(convert_to(p_text,'UTF8'),'sha256'),'hex');
  if authority.mode='ai_auto' and exists(select 1 from combat_consumer_private.publish_authorizations p
    join combat_consumer_private.narrative_claims c on c.id=p.claim_id
    where p.request_key=p_request and p.round_id=p_round and p.transaction_id=txid_current()
      and p.state='prepared' and p.text_sha256=text_sha and c.state='claimed'
      and c.context_version=ctx.context_version and c.control_version=authority.control_version) then return; end if;
  if authority.mode='ai_review' and exists(select 1 from public.combat_v2_ai_narrative_previews v
    join public.combat_v2_round_reports r on r.id=v.report_id and r.round_id=v.round_id
    where v.round_id=p_round and v.state='approved' and v.report_sha256=r.mechanics_sha256
      and v.body=btrim(p_text) and v.body_sha256=public.combat_v2_sha256(to_jsonb(btrim(p_text)))) then return; end if;
  raise exception 'ordinary_narrative_authority_invalid';
end $function$

CREATE OR REPLACE FUNCTION public.combat_v2_narrative_store(p_round uuid, p_kind text, p_text text, p_request_key uuid, p_author uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_r public.combat_v2_rounds%rowtype;
  v_rep public.combat_v2_round_reports%rowtype;
  v_location uuid;
  v_narrative_id uuid;
  v_message_id uuid;
  v_result jsonb;
  v_next uuid;
  v_active_teams int;
begin
  perform public.combat_v2_lock_round(p_round);
  select * into v_r from public.combat_v2_rounds where id=p_round for update;
  select * into v_rep from public.combat_v2_round_reports where round_id=p_round for update;
  perform public.combat_v2_assert_operational(p_round,p_request_key,true);
  perform combat_consumer_private.before_publish(p_round,p_kind,p_text,p_request_key,p_author);

  if v_r.id is null or v_rep.id is null or v_r.state<>'risolto' then
    perform public.combat_v2_fail('referto_non_completo','Il round non ha un referto risolto.',409,p_request_key,'{}');
  end if;
  if v_rep.narration_state='pubblicata' then
    perform public.combat_v2_fail('round_gia_narrato','Il round è già narrato.',409,p_request_key,'{}');
  end if;
  if length(btrim(coalesce(p_text,''))) not between 1 and 5000 then
    perform public.combat_v2_fail('intento_non_valido','Testo narrativo non valido.',422,p_request_key,'{}');
  end if;

  select s.location_id into v_location
    from public.combat_v2_sessions s
   where s.id=v_r.session_id;
  if v_location is null then
    perform public.combat_v2_fail('sessione_inesistente','Sessione inesistente.',404,p_request_key,'{}');
  end if;

  insert into public.combat_v2_narratives(
    round_id,report_id,kind,body,author_user,request_key
  ) values(
    p_round,v_rep.id,p_kind,btrim(p_text),p_author,p_request_key
  ) returning id into v_narrative_id;

  -- Nessun sender_user e nessun character_id: in chat parla Fato; l'identità
  -- reale resta nell'audit combat_v2_narratives.author_user. Il trigger REC
  -- ignora la riga perché character_id è nullo.
  insert into public.messages(location_id,character_id,author_name,body,kind)
  values(v_location,null,'Fato',btrim(p_text),'fato')
  returning id into v_message_id;

  update public.combat_v2_round_reports
     set narration_state='pubblicata',
         narrator_kind=case when p_kind='fato_umano' then 'umano' else 'ia' end,
         message_id=v_message_id,
         narrated_at=clock_timestamp()
   where id=v_rep.id;

  update public.combat_v2_rounds
     set phase='narrato',state='narrato',narrated_at=clock_timestamp()
   where id=p_round;

  select count(distinct team_key) into v_active_teams
    from public.combat_v2_actors
   where session_id=v_r.session_id and state='attivo' and companion_id is null;

  if v_active_teams>=2 then
    insert into public.combat_v2_rounds(session_id,round_no,evaluation_mode)
    values(v_r.session_id,v_r.round_no+1,v_r.evaluation_mode)
    returning id into v_next;
  else
    update public.combat_v2_sessions set state='risolto' where id=v_r.session_id;
  end if;

  v_result:=public.combat_v2_envelope(p_request_key,jsonb_build_object(
    'narrative_id',v_narrative_id,
    'message_id',v_message_id,
    'next_round_id',v_next,
    'encounter_resolved',v_active_teams<2
  ));
  perform combat_consumer_private.after_publish(p_round,v_next);
  return v_result;
end
$function$

CREATE OR REPLACE FUNCTION public.combat_v2_round_narrate_ai_apply(p_round uuid, p_report_sha256 text, p_text text, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event jsonb;
  v_event_id uuid;
  v_result jsonb;
  v_preview public.combat_v2_ai_narrative_previews%rowtype;
  v_round public.combat_v2_rounds%rowtype;
  v_report public.combat_v2_round_reports%rowtype;
  v_location uuid;
  v_message_id uuid;
  v_narrative_id uuid;
  v_next uuid;
begin
  if not public.combat_v2_is_service() then
    perform public.combat_v2_fail('controllo_revocato','Porta riservata al servizio.',403,p_request_key,'{}');
  end if;
  select * into v_preview
    from public.combat_v2_ai_narrative_previews
   where round_id=p_round and report_sha256=p_report_sha256
     and body_sha256=public.combat_v2_sha256(to_jsonb(btrim(p_text))) and body=btrim(p_text)
   for update;
  if v_preview.id is null or v_preview.state<>'approved' then
    perform public.combat_v2_fail('controllo_revocato','La narrazione IA richiede anteprima e approvazione Staff.',409,p_request_key,'{}');
  end if;
  v_event:=public.combat_v2_event_begin(
    p_round,p_request_key,'combat_v2_round_narrate_ai_apply',
    jsonb_build_object(
      'round',p_round,'report_sha256',p_report_sha256,
      'preview_id',v_preview.id,'text_sha256',v_preview.body_sha256
    ),null
  );
  if (v_event->>'replay')::boolean then return v_event->'result'; end if;
  v_event_id:=(v_event->>'event_id')::uuid;

  perform public.combat_v2_lock_round(p_round);
  select * into v_round from public.combat_v2_rounds where id=p_round for update;
  select * into v_report from public.combat_v2_round_reports where round_id=p_round for update;

  if v_round.state='narrato'
     and v_report.narration_state='ritirata'
     and v_report.message_id is null then
    perform public.combat_v2_assert_operational(p_round,p_request_key,true);
    select s.location_id into v_location
      from public.combat_v2_sessions s
     where s.id=v_round.session_id;
    select nx.id into v_next
      from public.combat_v2_rounds nx
     where nx.session_id=v_round.session_id
       and nx.round_no=v_round.round_no+1;
    if v_location is null or v_next is null
       or not exists (
         select 1 from public.combat_v2_narrative_retractions nr
          where nr.report_id=v_report.id
       ) then
      perform public.combat_v2_fail('referto_non_completo','Ripubblicazione non autorizzabile.',409,p_request_key,'{}');
    end if;
    update public.combat_v2_narratives
       set body=btrim(p_text), kind='fato_ia', author_user=null, request_key=p_request_key
     where round_id=p_round
     returning id into v_narrative_id;
    if v_narrative_id is null then
      perform public.combat_v2_fail('referto_non_completo','Narrazione ritirata non trovata.',409,p_request_key,'{}');
    end if;
    insert into public.messages(location_id,character_id,author_name,body,kind)
    values(v_location,null,'Fato',btrim(p_text),'fato')
    returning id into v_message_id;
    update public.combat_v2_round_reports
       set narration_state='pubblicata', narrator_kind='ia',
           message_id=v_message_id, narrated_at=clock_timestamp()
     where id=v_report.id;
    update public.combat_v2_ai_narrative_previews
       set state='published',published_at=clock_timestamp()
     where id=v_preview.id;
    v_result:=public.combat_v2_envelope(p_request_key,jsonb_build_object(
      'narrative_id',v_narrative_id,'message_id',v_message_id,
      'next_round_id',v_next,'encounter_resolved',false,'replacement',true
    ));
    return public.combat_v2_event_complete(v_event_id,v_result);
  end if;

  v_result:=public.combat_v2_narrative_store(p_round,'fato_ia',p_text,p_request_key,null);
  update public.combat_v2_ai_narrative_previews
     set state='published',published_at=clock_timestamp()
   where id=v_preview.id;
  return public.combat_v2_event_complete(v_event_id,v_result);
end
$function$

CREATE OR REPLACE FUNCTION public.combat_v2_round_narrate_human(p_round uuid, p_text text, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_m public.master_v2_sessions%rowtype; v_event jsonb; v_event_id uuid; v_result jsonb;
begin
  if combat_consumer_private.owns_round(p_round) then perform public.combat_v2_lock_round(p_round); end if;
  select m.* into v_m from public.combat_v2_rounds r join public.combat_v2_sessions s on s.id=r.session_id join public.master_v2_sessions m on m.id=coalesce(s.master_session_id,combat_consumer_private.narrative_master(s.id)) where r.id=p_round for update of m;
  if v_m.id is null or v_m.master_user<>v_uid then perform public.combat_v2_fail('master_non_proprietario','Solo il Master corrente può narrare.',403,p_request_key,'{}'); end if;
  v_event:=public.combat_v2_event_begin(p_round,p_request_key,'combat_v2_round_narrate_human',jsonb_build_object('round',p_round,'text',p_text),v_m.control_version);
  if (v_event->>'replay')::boolean then return v_event->'result'; end if; v_event_id:=(v_event->>'event_id')::uuid;
  v_result:=public.combat_v2_narrative_store(p_round,'fato_umano',p_text,p_request_key,v_uid);
  return public.combat_v2_event_complete(v_event_id,v_result);
end $function$

