CREATE OR REPLACE FUNCTION public.combat_consumer_scene_status_v2(p_round uuid, p_report_sha256 text, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE id uuid;
BEGIN
  IF NOT combat_consumer_private.is_service_request() THEN RAISE EXCEPTION 'scene_service_required'; END IF;
  SELECT a.claim_id INTO id FROM combat_consumer_private.scene_attempts_v2 a JOIN combat_consumer_private.narrative_claims c ON c.id=a.claim_id
    WHERE a.round_id=p_round AND c.report_sha256=p_report_sha256 AND a.request_key=p_request_key;
  IF id IS NULL THEN RETURN null; END IF;
  RETURN combat_consumer_private.scene_record_v2(id);
END $function$

CREATE OR REPLACE FUNCTION public.combat_consumer_narrative_claim_v1(p_round uuid, p_report_sha256 text, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ctx combat_consumer_private.activities%rowtype; report public.combat_v2_round_reports%rowtype;
  authority combat_consumer_private.narrative_authorities%rowtype;
  claim combat_consumer_private.narrative_claims%rowtype; payload jsonb;
begin
  if not combat_consumer_private.is_service_request() then perform combat_consumer_private.fail('not_participant'); end if;
  if p_request_key is null then perform combat_consumer_private.fail('identifier_invalid'); end if;
  perform public.combat_v2_lock_round(p_round);
  if exists(select 1 from combat_consumer_private.recovery_claims_v1 where round_id=p_round) then raise exception 'legacy_claim_recovery_fenced'; end if;
  select * into ctx from combat_consumer_private.activities where exchange_id=p_round for update;
  if ctx.session_id is null or ctx.phase<>'resolved' then
    return jsonb_build_object('should_call_provider',false,'state','not_ready');
  end if;
  select * into report from public.combat_v2_round_reports where round_id=p_round for update;
  select * into authority from combat_consumer_private.narrative_authorities where session_id=ctx.session_id for update;
  select * into claim from combat_consumer_private.narrative_claims where round_id=p_round for update;
  if claim.id is not null then
    if claim.request_key<>p_request_key or claim.report_sha256 is distinct from p_report_sha256 then
      perform combat_consumer_private.fail('request_key_conflict',p_request_key);
    end if;
    if claim.state='claimed' and claim.expires_at<clock_timestamp() then
      update combat_consumer_private.narrative_claims set state='expired',failure_code='timeout' where id=claim.id;
      claim.state:='expired';
    end if;
    -- Ripetizione non consegna di nuovo il permesso a chiamare il provider.
    return jsonb_build_object('claim_id',claim.id,'should_call_provider',false,'state',claim.state,
      'completion',claim.completion_result);
  end if;
  if not combat_consumer_private.narrative_allowed(ctx.session_id)
    or authority.mode is distinct from 'ai_auto' then
    return jsonb_build_object('should_call_provider',false,'state','disabled');
  end if;
  if report.id is null or report.mechanics_sha256 is distinct from p_report_sha256 or report.narration_state<>'attesa' then
    perform combat_consumer_private.fail('context_stale',p_request_key);
  end if;
  payload:=combat_consumer_private.narrative_context(p_round);
  insert into combat_consumer_private.narrative_claims(session_id,round_id,report_id,report_sha256,
    context_version,control_version,context_payload,context_sha256,request_key,state,expires_at)
    values(ctx.session_id,p_round,report.id,report.mechanics_sha256,ctx.context_version,authority.control_version,
      payload,public.combat_v2_sha256(payload),p_request_key,'claimed',clock_timestamp()+interval '60 seconds') returning * into claim;
  return jsonb_build_object('claim_id',claim.id,'should_call_provider',true,'state',claim.state,
    'report_id',claim.report_id,'round_id',claim.round_id,
    'report_sha256',claim.report_sha256,'context_sha256',claim.context_sha256,'control_version',claim.control_version,
    'edge_revision',case when payload->>'genere'='rinuncia' then 'ordinary-rinuncia/1' when payload->>'genere'='azione_risolta' then 'ordinary-facts/1' else 'ordinary-adapter/1' end,'validator_revision',case when payload->>'genere'='rinuncia' then 'combat-rinuncia/1' when payload->>'genere'='azione_risolta' then 'combat-facts/1' else 'combat-narratore-v18-existing/1' end,
    'provider','openai','model','gpt-5.6-luna','expires_at',claim.expires_at,'context',payload);
end $function$

CREATE OR REPLACE FUNCTION public.combat_consumer_scene_permit_v2(p_round uuid, p_report_sha256 text, p_request_key uuid, p_scene_sha256 text, p_control_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_claim uuid; a combat_consumer_private.scene_attempts_v2%ROWTYPE; c combat_consumer_private.narrative_claims%ROWTYPE;
BEGIN
  v_claim:=combat_consumer_private.scene_lock_v2(p_round,p_report_sha256,p_request_key);
  SELECT * INTO STRICT a FROM combat_consumer_private.scene_attempts_v2 WHERE claim_id=v_claim;
  SELECT * INTO STRICT c FROM combat_consumer_private.narrative_claims WHERE narrative_claims.id=v_claim;
  IF a.scene_sha256 IS DISTINCT FROM p_scene_sha256 OR c.control_version IS DISTINCT FROM p_control_version THEN RAISE EXCEPTION 'scene_permit_binding_changed'; END IF;
  IF a.state<>'claimed' THEN RETURN combat_consumer_private.scene_record_v2(v_claim); END IF;
  IF NOT combat_consumer_private.scene_current_v2(v_claim) OR c.expires_at<=clock_timestamp()+interval '13 seconds' THEN
    UPDATE combat_consumer_private.scene_attempts_v2 SET state='failed',failure_code='context_or_lease_changed' WHERE claim_id=v_claim;
    UPDATE combat_consumer_private.narrative_claims SET state='failed',failure_code='context_changed' WHERE narrative_claims.id=v_claim;
    RETURN combat_consumer_private.scene_record_v2(v_claim);
  END IF;
  UPDATE combat_consumer_private.scene_attempts_v2 SET state='provider_reserved',permit_at=clock_timestamp() WHERE claim_id=v_claim;
  UPDATE combat_consumer_private.narrative_claims SET expires_at=clock_timestamp()+interval '60 seconds' WHERE narrative_claims.id=v_claim;
  RETURN combat_consumer_private.scene_record_v2(v_claim)||jsonb_build_object('granted_now',true);
END $function$

CREATE OR REPLACE FUNCTION public.combat_consumer_scene_save_v2(p_round uuid, p_report_sha256 text, p_request_key uuid, p_result_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_claim uuid; a combat_consumer_private.scene_attempts_v2%ROWTYPE;
  c combat_consumer_private.narrative_claims%ROWTYPE; result jsonb; fingerprint text;
BEGIN
  v_claim:=combat_consumer_private.scene_lock_v2(p_round,p_report_sha256,p_request_key);
  IF p_result_text IS NULL OR octet_length(p_result_text)>65536 THEN RAISE EXCEPTION 'scene_delivery_transport_overflow'; END IF;
  result:=p_result_text::jsonb;
  PERFORM combat_consumer_private.validate_scene_result_v2(result);
  fingerprint:=encode(extensions.digest(convert_to(p_result_text,'UTF8'),'sha256'),'hex');
  SELECT * INTO STRICT a FROM combat_consumer_private.scene_attempts_v2 WHERE claim_id=v_claim;
  SELECT * INTO STRICT c FROM combat_consumer_private.narrative_claims WHERE id=v_claim;
  IF a.result_sha256 IS NOT NULL THEN
    IF a.result_sha256 IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'scene_result_conflict'; END IF;
    RETURN combat_consumer_private.scene_record_v2(v_claim);
  END IF;
  IF a.state<>'provider_reserved' OR a.permit_at IS NULL OR c.expires_at<=clock_timestamp()
    OR NOT combat_consumer_private.scene_current_v2(v_claim)
    OR result->>'report_sha256' IS DISTINCT FROM c.report_sha256
    OR result->>'context_sha256' IS DISTINCT FROM a.scene_sha256
    OR (result->>'control_version')::bigint IS DISTINCT FROM c.control_version THEN
    UPDATE combat_consumer_private.scene_attempts_v2 SET state='failed',failure_code='context_or_lease_changed' WHERE claim_id=v_claim;
    UPDATE combat_consumer_private.narrative_claims SET state='failed',failure_code='context_changed' WHERE id=v_claim;
    RETURN combat_consumer_private.scene_record_v2(v_claim);
  END IF;
  IF result->>'status'='succeeded' AND encode(extensions.digest(convert_to(result->>'text','UTF8'),'sha256'),'hex')
    IS DISTINCT FROM result->>'text_sha256' THEN RAISE EXCEPTION 'scene_text_hash_changed'; END IF;
  UPDATE combat_consumer_private.scene_attempts_v2 SET result_bytes=p_result_text,result_payload=result,result_sha256=fingerprint,
    provider_response_id=result->>'provider_response_id',result_at=clock_timestamp(),
    state=CASE WHEN result->>'status'='succeeded' THEN 'generated' ELSE 'failed' END,
    failure_code=result->>'failure_code',completion=CASE WHEN result->>'status'='failed'
      THEN jsonb_build_object('status','not_published','reason',result->>'failure_code') ELSE NULL END WHERE claim_id=v_claim;
  IF result->>'status'='failed' THEN
    UPDATE combat_consumer_private.narrative_claims SET state='failed',failure_code=result->>'failure_code',
      provider_response_id=result->>'provider_response_id',provider_request_sha256=result->>'provider_request_sha256',
      raw_output_sha256=result->>'raw_output_sha256' WHERE id=v_claim;
  END IF;
  RETURN combat_consumer_private.scene_record_v2(v_claim);
END $function$

CREATE OR REPLACE FUNCTION public.combat_consumer_scene_complete_v2(p_round uuid, p_report_sha256 text, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_claim uuid; a combat_consumer_private.scene_attempts_v2%ROWTYPE; result jsonb; receipt jsonb;
BEGIN
  v_claim:=combat_consumer_private.scene_lock_v2(p_round,p_report_sha256,p_request_key);
  SELECT * INTO STRICT a FROM combat_consumer_private.scene_attempts_v2 WHERE claim_id=v_claim;
  IF a.state IN('published','failed') THEN RETURN combat_consumer_private.scene_record_v2(v_claim); END IF;
  IF a.state<>'generated' OR a.result_payload IS NULL THEN RAISE EXCEPTION 'scene_result_not_ready'; END IF;
  -- La generazione è già finita e persistita entro la lease: la consegna idempotente può proseguire dopo,
  -- purché authority, report, stato protetto e versione contesto siano ancora identici.
  IF NOT combat_consumer_private.scene_current_v2(v_claim) THEN
    UPDATE combat_consumer_private.scene_attempts_v2 SET state='failed',failure_code='context_changed' WHERE claim_id=v_claim;
    UPDATE combat_consumer_private.narrative_claims SET state='failed',failure_code='context_changed' WHERE id=v_claim;
    RETURN combat_consumer_private.scene_record_v2(v_claim);
  END IF;
  result:=a.result_payload;
  PERFORM combat_consumer_private.validate_scene_result_v2(result);
  INSERT INTO combat_consumer_private.publish_authorizations
    VALUES(p_request_key,p_round,v_claim,result->>'text_sha256',txid_current(),'prepared');
  -- Stessa porta reale del prodotto, stessi trigger, ricevuta e isolamento. Nessun inserimento messaggi alternativo.
  receipt:=public.combat_v2_narrative_store(p_round,'fato_ia',result->>'text',p_request_key,null);
  UPDATE combat_consumer_private.publish_authorizations SET state='consumed' WHERE request_key=p_request_key;
  UPDATE combat_consumer_private.narrative_claims SET state='completed',completion_sha256=public.combat_v2_sha256(result),
    completion_result=receipt,provider_response_id=result->>'provider_response_id',provider_request_sha256=result->>'provider_request_sha256',
    raw_output_sha256=result->>'raw_output_sha256' WHERE id=v_claim;
  UPDATE combat_consumer_private.scene_attempts_v2 SET state='published',completion=receipt WHERE claim_id=v_claim;
  RETURN combat_consumer_private.scene_record_v2(v_claim);
END $function$
